+                    _i18n?.T("DesktopPet 模型连接") ?? "DesktopPet 模型连接",
+                    MessageBoxButton.OK,
+                    MessageBoxImage.Warning);
+            }
+            else if (result.CleanupErrors.Count > 0)
+            {
+                MessageBox.Show(
+                    _i18n?.T("模型凭据已迁移，但旧凭据清理失败；下次启动会重试。")
